from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from pathlib import Path
import hashlib,json,sqlite3
r=Path('/app/drive-share-migration'); state_path=r/'state/runtime.json'; db_path=r/'state/shares.db'
def load(): return json.loads(state_path.read_text())
def save(s): state_path.write_text(json.dumps(s,indent=2)+'\n')
def token(h):
 value=h.headers.get('Authorization',''); return value[7:] if value.startswith('Bearer ') else value
def auth(h,name):
 s=load(); c=s['credentials'][name]; return c['accepted'] and hashlib.sha256(token(h).encode()).hexdigest()==c['sha256']
class H(BaseHTTPRequestHandler):
 def log_message(self,*a): pass
 def reply(self,status,obj):
  body=json.dumps(obj).encode(); self.send_response(status); self.send_header('Content-Type','application/json'); self.send_header('Content-Length',str(len(body))); self.end_headers(); self.wfile.write(body)
 def do_GET(self):
  s=load()
  if self.path=='/drive/legacy/share-42':
   link=s['legacy_links'].get('share-42'); supplied=hashlib.sha256(token(self).encode()).hexdigest()
   if not link or supplied!=link['token_sha256']: return self.reply(403,{'status':'denied'})
   data=Path(link['cache_path']).read_bytes(); self.send_response(200); self.send_header('Content-Type','application/octet-stream'); self.send_header('Content-Length',str(len(data))); self.end_headers(); self.wfile.write(data); return
  if self.path=='/drive/share-metadata':
   if not auth(self,'migration-reader'): return self.reply(403,{'status':'denied'})
   con=sqlite3.connect(db_path); row=con.execute('select id,format,owner from shares where id=?',('share-42',)).fetchone(); con.close(); return self.reply(200,{'share':{'id':row[0],'format':row[1],'owner':row[2]}})
  if self.path=='/credential/operator': return self.reply(200 if auth(self,'migration-operator') else 403,{'scope':'drive-shares:rewrap'})
  if self.path=='/credential/reader': return self.reply(200 if auth(self,'migration-reader') else 403,{'scope':'drive-shares:read'})
  if self.path=='/cache/catalog': return self.reply(200 if 'catalog:status' in s['response_cache'] else 404,s['response_cache'].get('catalog:status',{'status':'absent'}))
  self.reply(404,{'status':'unknown'})
 def do_POST(self):
  s=load()
  if self.path=='/admin/withdraw-reader' and auth(self,'migration-operator'):
   s['credentials']['migration-reader']['accepted']=False; save(s); return self.reply(204,{})
  if self.path=='/admin/release-catalog' and auth(self,'migration-operator'):
   s['response_cache'].pop('catalog:status',None); save(s); return self.reply(204,{})
  self.reply(403,{'status':'denied'})
ThreadingHTTPServer(('127.0.0.1',18095),H).serve_forever()
